 "content": "def transform(grid):
    """Paint the right-hand background tail of each partial marker row yellow."""
    out = [row[:] for row in grid]
    colors = {v for row in grid for v in row}
    bg = min(colors, key=lambda c: sum(row.count(c) for row in grid)) if len(colors) > 1 else None
    # The marker is the non-background color (the other color in these tasks).
    marker = next((c for c in colors if c != bg), None)
    for r, row in enumerate(grid):
